<script>(function(){const sb=document.querySelector('.rts-sidebar');const toggle=document.getElementById('sidebarToggle');function setCollapsed(value){sb?.classList.toggle('collapsed',value);document.body.classList.toggle('sidebar-collapsed',value);if(toggle)toggle.innerHTML=value?'<i class="fa-solid fa-angles-right"></i>':'<i class="fa-solid fa-angles-left"></i>';localStorage.setItem('rts_sidebar_collapsed',value?'1':'0');}setCollapsed(localStorage.getItem('rts_sidebar_collapsed')==='1');toggle?.addEventListener('click',function(e){e.preventDefault();setCollapsed(!sb.classList.contains('collapsed'));});document.getElementById('rtsMenu')?.addEventListener('click',()=>sb?.classList.toggle('open'));})();</script>
